function setMute(m){ muted=m; if(master) master.gain.value=m?0:0.5; }

// ---- Starfield ------------------------------------------------------------
const stars=[];
for(let i=0;i<90;i++) stars.push({x:irand(0,W-1),y:irand(0,H-1),
  sp:rand(0.05,0.5),ph:rand(0,6.28),spk:rand(0.05,0.25),
  c:pick(['#ffffff','#ffd27a','#7fdcff','#ffb3e6','#c7a3ff'])});
function updateStars(dt){ for(const s of stars){ s.y+=s.sp*dt/60; if(s.y>H)s.y-=H; s.ph+=s.spk*dt/60; } }
function drawStars(){ for(const s of stars){ const a=0.35+0.65*(0.5+0.5*Math.sin(s.ph));
  ctx.globalAlpha=a; ctx.fillStyle=s.c; ctx.fillRect(s.x|0,s.y|0,1,1); } ctx.globalAlpha=1; }

// ---- Pixel sprites ---------------------------------------------------------
// Each sprite is an array of strings; chars map to palette colours.
const PAL={'.':null,'W':'#ffffff','R':'#ff3b3b','G':'#39e05a','B':'#3aa0ff','Y':'#ffe23a',
  'O':'#ff9d2e','P':'#c06bff','C':'#39e0ff','K':'#000000','D':'#7a1010'};
const SPR={
  player:[
    "....W....",
    "...WWW...",
    "..WWWWW..",
    ".WWRWRWW.",
    ".WWRWRWW.",
    ".RRRRRRR.",
    ".RWRRRWR.",
