};
function recolor(rows,c1,c2){ return rows.map(r=>r.replace(/g/g,c1).replace(/b/g,c2)); }
// build recolour variants (lowercase g/b are the tintable pixels)
SPR.zakF2=recolor(SPR.zakF,'Y','B'); SPR.zakS2=recolor(SPR.zakS,'Y','B');
SPR.bosPF=recolor(SPR.bosF,'P','B'); SPR.bosPS=recolor(SPR.bosS,'P','B');
SPR.bosBF=recolor(SPR.bosF,'B','P'); SPR.bosBS=recolor(SPR.bosS,'B','P');

function drawSprite(cx,cy,rows){
  const h=rows.length, w=rows[0].length;
  const ox=Math.round(cx-w/2), oy=Math.round(cy-h/2);
  for(let y=0;y<h;y++){ const row=rows[y];
    for(let x=0;x<w;x++){ const ch=row[x]; if(ch==='.')continue;
      const col=PAL[ch]; if(!col)continue; ctx.fillStyle=col; ctx.fillRect(ox+x,oy+y,1,1); } }
}
function enemyRows(type,frame,hit){
  if(type==='zako') return frame?SPR.zakF2:SPR.zakF;
  if(type==='goei') return frame?SPR.goeS:SPR.goeF;
  if(hit) return frame?SPR.bosPS:SPR.bosPF;
  return frame?SPR.bosF:SPR.bosS;
}

// ---- Formation layout ------------------------------------------------------
const ROWS=[
  {type:'boss',n:4, y:42, gap:40},
  {type:'goei',n:8, y:64, gap:26},
  {type:'goei',n:8, y:82, gap:26},
  {type:'zako',n:10,y:104,gap:20},
  {type:'zako',n:10,y:122,gap:20},
];
function formationSlots(){
  const out=[];
  for(const r of ROWS){
    const total=r.n*r.gap, sx=W/2-total/2+r.gap/2;
    for(let i=0;i<r.n;i++) out.push({x:sx+i*r.gap, y:r.y, type:r.type});
  }
  return out;
}
const BASE_SLOTS=formationSlots();

// ---- Game state ------------------------------------------------------------
const ST_TITLE=0,ST_STAGE=1,ST_PLAY=2,ST_OVER=3;
const G={
  state:ST_TITLE, time:0, frame:0,
  stage:1, score:0, high:0, extraShipAwarded:20000,
  ships:3, livesLost:0, shotsFired:0, hits:0,
  enemies:[], pShots:[], eShots:[], parts:[], texts:[], explosions:[],
  player:null, captured:null, docked:false,
  beam:null, diveTimer:0, waveTimer:0, challengeHits:0,
  paused:false, readyT:0, respawnT:0, stageT:0, overT:0,
  swayPhase:0, breathPhase:0, entryDone:false,
};
try{ G.high=parseInt(localStorage.getItem('galaga_high')||'0',10)||0; }catch(e){ G.high=0; }

function newPlayer(){
  return { x:W/2, y:H-24, alive:true, invuln:0, dead:false, halfL:true, halfR:true };
}
G.player=newPlayer();

// ---- State transitions -----------------------------------------------------
function resetRun(){
  G.stage=1; G.score=0; G.ships=3; G.livesLost=0; G.shotsFired=0; G.hits=0;
  G.extraShipAwarded=20000; G.docked=false; G.captured=null;
  startStage();
}
function startStage(){
  G.enemies=[]; G.pShots=[]; G.eShots=[]; G.parts=[]; G.texts=[]; G.explosions=[];
  G.beam=null; G.challengeHits=0; G.entryDone=false; G.swayPhase=0; G.breathPhase=0;
  G.diveTimer=rand(60,120); G.waveTimer=0;
  G.player=newPlayer(); G.state=ST_STAGE; G.stageT=0;
  SFX.stage();
}
function gameOver(){
  G.state=ST_OVER; G.overT=0;
  if(G.score>G.high){ G.high=G.score; try{ localStorage.setItem('galaga_high',String(G.high)); }catch(e){} }
  SFX.over();
}

// ---- Enemy factory ---------------------------------------------------------
function makeEnemy(slot){
  return { type:slot.type, home:{x:slot.x,y:slot.y}, x:slot.x, y:slot.y,
    state:'enter', phase:0, path:null, px:0, py:0, facing:1,
    hit:0, diving:false, escort:[], capturedRef:null,
    tx:slot.x, ty:slot.y, vx:0, vy:0, angle:0, flap:0,
    shootT:rand(30,90), enterDelay:0, slotIndex:slot.i||0 };
}
function spawnFormation(){
  const slots=BASE_SLOTS;
  for(let i=0;i<slots.length;i++){ const e=makeEnemy(slots[i]); e.slotIndex=i; G.enemies.push(e); }
  // group entry delays: bosses first, then goei, then zaks
  let d=0;
  for(const e of G.enemies){
    if(e.type==='boss'){ e.enterDelay=d; }
  }
  d+=120;
  for(const e of G.enemies){ if(e.type==='goei') e.enterDelay=d; }
  d+=120;
  for(const e of G.enemies){ if(e.type==='zako') e.enterDelay=d; }
}

// curved entry path from off-screen to a slot
function entryPath(e){
  const side=e.home.x<W/2?-1:1;
  const sx=side<0? -12 : W+12;
  const sy=rand(0,40);
  const cx=lerp(sx,e.home.x,0.5)+side*rand(-30,30);
  const cy=rand(60,120);
  return {sx,sy,cx,cy,ex:e.home.x,ey:e.home.y};
}
function quadPoint(p,t){
  const u=1-t;
  return { x:u*u*p.sx + 2*u*t*p.cx + t*t*p.ex,
           y:u*u*p.sy + 2*u*t*p.cy + t*t*p.ey };
}

// ---- Dive paths ------------------------------------------------------------
function divePath(e){
  const dir=e.facing;
  const sx=e.x, sy=e.y;
  const ex=clamp(G.player.x, 10, W-10);
  const cx=clamp(sx+dir*rand(20,60), 8, W-8);
  const cy=rand(sy+30, sy+90);
  return {sx,sy,cx,cy,ex,ey:H+20};
}
function startDive(e,escortCount){
  e.state='dive'; e.diving=true; e.path=divePath(e); e.phase=0; e.px=0; e.py=0;
  e.escort=[]; e.capturedRef=null;
  // attach escorts (goeis) for boss dives
  if(e.type==='boss' && escortCount>0){
    const free=G.enemies.filter(o=>o!==e && o.type==='goei' && o.state==='form');
    for(let i=0;i<escortCount && i<free.length;i++){
      const g=free[i]; g.state='dive'; g.diving=true; g.path=divePath(g); g.phase=0; g.px=0; g.py=0;
      e.escort.push(g);
    }
  }
}
function reenterTop(e){
  e.x=e.tx; e.y=-12; e.state='return'; e.phase=0; e.diving=false; e.escort=[];
}

// ---- Tractor beam / capture ------------------------------------------------
function startBeam(boss){
  G.beam={boss, t:0, active:true, done:false};
  SFX.beam();
}
function doCapture(){
  if(!G.player.alive || !G.player.invuln<=0) return;
  const boss=G.beam.boss;
  // player becomes captured fighter above the boss
  const cap={ x:boss.x, y:boss.y-16, boss };
  G.captured=cap; boss.capturedRef=cap;
  G.player.alive=false; G.player.dead=true;
  G.ships--; G.livesLost++;
  SFX.capture();
  addText(boss.x, boss.y-24, 'CAPTURED!', COL.red, 60);
  if(G.ships<=0){ setTimeout(gameOver, 400); }
  else { G.respawnT=40; }
}
function freeCaptured(){
  if(!G.captured) return;
  const cap=G.captured; const boss=cap.boss; boss.capturedRef=null; G.captured=null;
  cap.x=boss.x; cap.y=boss.y; cap.freeing=true; cap.ty=H-24;
  G.parts.push({kind:'freed', x:cap.x, y:cap.y, ty:cap.ty});
  SFX.dual();
}

// ---- Scoring ---------------------------------------------------------------
function addScore(n,x,y,label,col){
  G.score+=n;
  if(label) addText(x,y,label,col||COL.white,40);
  while(G.score>=G.extraShipAwarded){
    G.ships++; G.extraShipAwarded+=70000;
    addText(W/2,H/2-10,'EXTRA SHIP!',COL.yellow,80); SFX.dual();
  }
  if(G.score>G.high) G.high=G.score;
}
function enemyPoints(e,diving){
  if(G.state===ST_PLAY && isChallenge()){ return 100; }
  if(e.type==='zako') return diving?100:50;
  if(e.type==='goei') return diving?160:80;
  // boss
  if(diving){
    const esc=e.escort?e.escort.length:0;
    return esc>=2?1600:(esc===1?800:400);
  }
  return 150;
}
function isChallenge(){ return G.stage===3 || ((G.stage-3)%4===0 && G.stage>3); }

// ---- Effects ----------------------------------------------------------------
function addExplosion(x,y,color){ G.explosions.push({x,y,t:0,color}); }
function addText(x,y,str,col,life){ G.texts.push({x,y,str,col,life,max:life}); }
function burst(x,y,color,n){ for(let i=0;i<(n||8);i++){ const a=rand(0,6.28),s=rand(0.2,1.4);
  G.parts.push({kind:'spark',x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:irand(10,22),color}); } }

// ---- Shooting --------------------------------------------------------------
function firePlayer(){
  if(!G.player.alive) return;
  const active=G.pShots.length;
  if(active>=2) return;
  G.shotsFired++;
  const px=G.player.x;
  if(G.docked && G.player.halfL && G.player.halfR){
    G.pShots.push({x:px-3,y:G.player.y-8,vy:-3.2});
    G.pShots.push({x:px+3,y:G.player.y-8,vy:-3.2});
  } else if(G.player.halfL) G.pShots.push({x:px-2,y:G.player.y-8,vy:-3.2});
  else G.pShots.push({x:px+2,y:G.player.y-8,vy:-3.2});
  SFX.shot();
}
function enemyFire(x,y){ G.eShots.push({x,y,vy:2.2}); }

// ---- Update: enemies -------------------------------------------------------
function updateEnemies(dt){
  const canDive = G.state===ST_PLAY && !isChallenge() && G.player.alive && G.respawnT<=0;
  for(const e of G.enemies){
    e.flap+=dt*0.15;
    switch(e.state){
      case 'enter':{
        if(e.enterDelay>0){ e.enterDelay-=dt; break; }
        if(!e.path) e.path=entryPath(e);
        e.phase+=dt/110;
        if(e.phase>=1){ e.phase=1; e.state='form'; e.x=e.tx; e.y=e.ty; }
        else { const p=quadPoint(e.path,e.phase); e.x=p.x; e.y=p.y;
               e.tx=p.x; e.ty=p.y; e.facing=p.x>e.x?1:-1;
               if(canDive && Math.random()<0.004*dt) enemyFire(e.x,e.y+8); }
        break;
      }
      case 'form':{
        // breathing offset applied at render; keep logical home fixed
        e.x=e.home.x; e.y=e.home.y;
        break;
      }
      case 'dive':{
        if(!e.path) e.path=divePath(e);
        e.phase+=dt/(e.type==='boss'?95:80);
        if(e.phase>=1){
          // reached bottom -> re-enter from top
          e.x=e.tx; e.y=-12; e.state='return'; e.diving=false; e.escort=[];
        } else {
          const p=quadPoint(e.path,e.phase); e.x=p.x; e.y=p.y; e.tx=p.x; e.ty=p.y;
          e.facing=p.x>e.x?1:-1;
          if(canDive && Math.random()<0.01*dt) enemyFire(e.x,e.y+8);
        }
        break;
      }
      case 'beam':{
        e.x=e.tx; e.y=e.ty; // stationary during beam
        break;
      }
      case 'return':{
        // fly up to slot
        const dx=e.home.x-e.x, dy=e.home.y-e.y;
        const d=Math.hypot(dx,dy);
        if(d<3){ e.state='form'; e.x=e.home.x; e.y=e.home.y; e.diving=false; }
        else { e.x+=dx/d*2.2*dt/1; e.y+=dy/d*2.2*dt/1; }
        break;
      }
    }
  }
  // remove any destroyed enemies
  G.enemies=G.enemies.filter(e=>!e.dead);
}

// ---- Update: tractor beam --------------------------------------------------
function updateBeam(dt){
  const b=G.beam; if(!b) return;
  b.t+=dt;
  const boss=b.boss;
  if(boss.state!=='beam'){ G.beam=null; return; }
  // widen cone
  const prog=Math.min(1,b.t/30);
  b.prog=prog;
  // check player inside cone near bottom
  if(prog>=1 && G.player.alive && G.respawnT<=0){
    const halfW=14; // cone half-width at player's row
    if(Math.abs(G.player.x-boss.x)<halfW+4){
      doCapture();
      boss.state='form'; boss.x=boss.tx; boss.y=boss.ty;
      G.beam=null;
      return;
    }
  }
  if(b.t>110){ boss.state='form'; boss.x=boss.tx; boss.y=boss.ty; G.beam=null; }
}

// ---- Update: player --------------------------------------------------------
const keys={left:false,right:false,fire:false};
function updatePlayer(dt){
  const p=G.player;
  if(G.respawnT>0){ G.respawnT-=dt; if(G.respawnT<=0){ G.player=newPlayer(); G.readyT=60; } }
  if(G.readyT>0){ G.readyT-=dt; }
  if(!p.alive) return;
  if(p.invuln>0) p.invuln-=dt;
  const spd=1.7;
  if(keys.left)  p.x-=spd;
  if(keys.right) p.x+=spd;
  p.x=clamp(p.x,8,W-8);
  p.y=H-24;
  if(keys.fire && G.pShots.length<2 && G.readyT<=0) firePlayer();
}

// ---- Update: bullets -------------------------------------------------------
function updateShots(dt){
  for(const s of G.pShots){ s.y+=s.vy*dt; if(s.y<-6) s.dead=true; }
  for(const s of G.eShots){ s.y+=s.vy*dt; if(s.y>H+6) s.dead=true; }
  G.pShots=G.pShots.filter(s=>!s.dead);
  G.eShots=G.eShots.filter(s=>!s.dead);
}

// ---- Collisions ------------------------------------------------------------
function hitRect(x,y,w,h){ return {x:x-w/2,y:y-h/2,w,h}; }
function overlap(a,b){ return a.x<b.x+b.w && a.x+a.w>b.x && a.y<b.y+b.h && a.y+a.h>b.y; }
function collide(){
  const p=G.player;
  // player shots vs enemies
  for(const s of G.pShots){
    if(s.dead) continue;
    const sb=hitRect(s.x,s.y,2,4);
    for(const e of G.enemies){
      if(e.dead) continue;
      const eb=hitRect(e.x,e.y,10,10);
      if(overlap(sb,eb)){
        s.dead=true; G.hits++;
        if(e.type==='boss' && e.hit===0){
          e.hit=1; addScore(enemyPoints(e,false),e.x,e.y-10); SFX.bossHit();
          addExplosion(e.x,e.y,COL.green);
          if(e.state==='dive' && e.capturedRef){ freeCaptured(); }
        } else {
          destroyEnemy(e,true);
        }
        break;
      }
    }
  }
  // enemy shots vs player
  if(p.alive && p.invuln<=0){
    for(const s of G.eShots){
      if(s.dead) continue;
      const pb = G.docked ? hitRect(p.x,p.y,14,10) : hitRect(p.x,p.y,8,8);
      if(overlap(hitRect(s.x,s.y,2,4),pb)){ s.dead=true; killPlayer(); break; }
    }
  }
  // enemy ram vs player
  if(p.alive && p.invuln<=0){
    for(const e of G.enemies){
      if(e.dead) continue;
      const pb = G.docked ? hitRect(p.x,p.y,14,10) : hitRect(p.x,p.y,8,8);
      if(overlap(hitRect(e.x,e.y,10,10),pb)){
        killPlayer();
        if(e.state==='dive'||e.state==='enter') destroyEnemy(e,true);
        break;
      }
    }
  }
}
function destroyEnemy(e,byShot){
  if(e.dead) return;
  e.dead=true;
  const pts=enemyPoints(e,e.diving);
  addScore(pts,e.x,e.y-8);
  SFX.edest(); addExplosion(e.x,e.y, e.type==='boss'?COL.green:COL.orange);
  burst(e.x,e.y, e.type==='boss'?COL.green:COL.orange, 10);
  if(isChallenge()) G.challengeHits++;
  if(e.capturedRef){ /* captive lost with boss in formation */ }
  // escorts die with boss
  if(e.escort) for(const g of e.escort){ if(!g.dead){ g.dead=true; addScore(160,g.x,g.y-8); addExplosion(g.x,g.y,COL.red); } }
  // freed fighters land as dual
  checkFreed();
}
function checkFreed(){
  for(const pt of G.parts){
    if(pt.kind==='freed' && pt.ty!=null){
      pt.y+=(pt.ty-pt.y)*0.2;
      if(Math.abs(pt.ty-pt.y)<2){
        pt.done=true;
        if(G.player.alive){ G.docked=true; G.player.halfL=true; G.player.halfR=true;
          addText(G.player.x,G.player.y-16,'DUAL FIGHTER!',COL.cyan,70); }
      }
    }
  }
  G.parts=G.parts.filter(pt=>!(pt.kind==='freed'&&pt.done));
}
function killPlayer(){
  const p=G.player; if(!p.alive) return;
  if(G.docked){
    // lose one half
    if(p.halfL) p.halfL=false; else p.halfR=false;
    if(!p.halfL && !p.halfR){ G.docked=false; fullDeath(); }
    else { p.invuln=40; SFX.boom(); addExplosion(p.x,p.y,COL.red); }
  } else fullDeath();
}
function fullDeath(){
  const p=G.player; p.alive=false; p.dead=true; G.docked=false;
  G.ships--; G.livesLost++;
  SFX.boom(); addExplosion(p.x,p.y,COL.red); burst(p.x,p.y,COL.red,14);
  if(G.ships<=0){ gameOver(); }
  else G.respawnT=45;
}

// ---- Challenge stage -------------------------------------------------------
let challengeWave=0, challengeSpawned=0;
function startChallenge(){
  challengeWave=0; challengeSpawned=0; G.waveTimer=60;
}
function challengeWavePattern(wave){
  // looping figure patterns across screen
  const base=wave*1.1;
  return {base, amp:rand(20,50), freq:rand(0.03,0.06), speed:rand(0.6,1.0)};
}
function spawnChallengeWave(){
  const pat=challengeWavePattern(challengeWave);
  for(let i=0;i<8;i++){
    const e={ type:pick(['zako','goei']), x:-20-i*4, y:40+ (i%4)*14, state:'chall',
      pat, off:i*0.5, phase:0, flap:rand(0,6), hit:0, dead:false, diving:false,
      tx:0,ty:0, escort:[], capturedRef:null, facing:1, home:{x:0,y:0}, slotIndex:0, enterDelay:0 };
    G.enemies.push(e);
  }
  challengeWave++; challengeSpawned+=8;
}
function updateChallenge(dt){
  if(challengeSpawned<40){ G.waveTimer-=dt; if(G.waveTimer<=0){ spawnChallengeWave(); G.waveTimer=140; } }
  for(const e of G.enemies){
    if(e.state!=='chall') continue;
    e.phase+=dt*e.pat.speed/60;
    e.x=-20+e.phase*40+e.off*6;
    e.y=e.pat.base*0+ 60 + Math.sin(e.phase*e.pat.freq*10+e.off)*e.pat.amp;
    e.x=wrapX(e.x);
    e.flap+=dt*0.15;
    if(e.x>W+20){ e.dead=true; }
  }
  G.enemies=G.enemies.filter(e=>!e.dead);
  if(challengeSpawned>=40 && G.enemies.length===0){
    // stage complete
    const bonus = Math.floor(G.challengeHits/8)*1000 + (G.challengeHits>=40?10000:0);
    addScore(bonus,W/2,120,'BONUS '+bonus,COL.yellow);
    addText(W/2,140,'NUMBER OF HITS: '+G.challengeHits,COL.white,120);
    if(G.challengeHits>=40) addText(W/2,158,'PERFECT!',COL.cyan,140);
    G.stage++; startStage();
  }
}

// ---- Stage progression -----------------------------------------------------
function updatePlay(dt){
  if(isChallenge()){ updateChallenge(dt); }
  else {
    updateEnemies(dt);
    updateBeam(dt);
    // scheduling dives
    if(G.player.alive && G.respawnT<=0){
      G.diveTimer-=dt;
      if(G.diveTimer<=0){
        scheduleDive();
        const aggro=Math.min(0.6, G.stage*0.06);
        G.diveTimer=rand(70,150)-aggro*60;
      }
    }
    // sometimes a boss starts a beam instead of a normal dive
    maybeBeam(dt);
  }
  updateShots(dt);
  collide();
  // stage clear (non-challenge)
  if(!isChallenge() && G.enemies.length===0 && G.entryDone){
    G.stage++; startStage();
  }
}
function scheduleDive(){
  const forms=G.enemies.filter(e=>e.state==='form');
  if(!forms.length) return;
  const boss=forms.find(e=>e.type==='boss');
  if(boss && Math.random()<0.5){
    const esc=irand(0,2);
    startDive(boss,esc);
  } else {
    startDive(pick(forms),0);
  }
}
let beamCooldown=0;
function maybeBeam(dt){
  beamCooldown-=dt;
  if(beamCooldown>0 || G.beam) return;
  const chance=0.0015+G.stage*0.0008;
  if(Math.random()>chance) return;
  const boss=G.enemies.find(e=>e.type==='boss' && e.state==='form');
  if(!boss) return;
  boss.state='beam'; boss.tx=boss.x; boss.ty=boss.y;
  startBeam(boss);
  beamCooldown=240;
}

// ---- Update dispatcher -----------------------------------------------------
function update(dt){
  updateStars(dt);
  G.time+=dt;
  // effects always animate
  for(const e of G.explosions) e.t+=dt;
  G.explosions=G.explosions.filter(e=>e.t<14);
  for(const p of G.parts){ if(p.kind==='spark'){ p.x+=p.vx*dt; p.y+=p.vy*dt; p.life-=dt; } }
  G.parts=G.parts.filter(p=>p.kind!=='spark'||p.life>0);
  for(const t of G.texts) t.life-=dt;
  G.texts=G.texts.filter(t=>t.life>0);

  if(G.paused) return;

  switch(G.state){
    case ST_TITLE: break;
    case ST_STAGE:
      G.stageT+=dt;
      if(G.stageT>90){ G.state=ST_PLAY; if(isChallenge()) startChallenge(); else spawnFormation(); }
      break;
    case ST_PLAY:
      updatePlayer(dt);
      updatePlay(dt);
      break;
    case ST_OVER:
      G.overT+=dt;
      if(G.overT>240){ G.state=ST_TITLE; }
      break;
  }
  // mark entry done when all settled
  if(G.state===ST_PLAY && !isChallenge()){
    if(!G.entryDone && G.enemies.every(e=>e.state==='form')) G.entryDone=true;
  }
}

// ---- Rendering -------------------------------------------------------------
function drawHUD(){
  ctx.font='8px "Courier New",monospace'; ctx.textBaseline='top';
  ctx.fillStyle=COL.white; ctx.fillText('1UP', 6, 4);
