}
function badgeVal(stage){
  const seq=[1,5,10,20,30,50];
  if(stage<=seq.length) return seq[stage-1];
  return 50*((stage-seq.length+1));
}
function drawBadges(){
  const shown=Math.min(G.stage,6);
  const bx=W-8-shown*10, by=H-12;
  for(let i=0;i<shown;i++){
    const x=bx+i*10;
    const val=badgeVal(i+1);
    ctx.fillStyle='#1b2a55'; ctx.fillRect(x,by,8,10);
    ctx.strokeStyle='#3a5bb0'; ctx.strokeRect(x+.5,by+.5,7,9);
