}
function drawPlayer(){
  const p=G.player; if(!p.alive) return;
  if(p.invuln>0 && (Math.floor(G.time/3)&1)) return; // blink
  if(G.docked && p.halfL && p.halfR){
    drawSprite(p.x-4,p.y,SPR.player); drawSprite(p.x+4,p.y,SPR.player);
  } else if(p.halfL) drawSprite(p.x-3,p.y,SPR.player);
  else drawSprite(p.x+3,p.y,SPR.player);
