function drawEnemies(){
  const breath = (G.entryDone && !isChallenge()) ? 1+0.06*Math.sin(G.breathPhase) : 1;
  const sway  = (G.entryDone && !isChallenge()) ? 6*Math.sin(G.swayPhase) : 0;
  for(const e of G.enemies){
    if(e.dead) continue;
    let rx=e.x, ry=e.y;
    if(e.state==='form'){ rx=e.home.x+sway; ry=e.home.y*(breath-1)+e.home.y; }
    const frame=(Math.floor(e.flap)%2)===0;
