    const b=G.beam, boss=b.boss, prog=b.prog||0;
    const topY=boss.y+8, botY=H;
    const topHalf=4, botHalf=14*prog;
    ctx.save(); ctx.globalAlpha=0.35+0.2*Math.sin(G.time*0.4);
    const grd=ctx.createLinearGradient(0,topY,0,botY);
    grd.addColorStop(0,'rgba(60,120,255,0.5)'); grd.addColorStop(1,'rgba(60,120,255,0.05)');
    ctx.fillStyle=grd;
    ctx.beginPath();
    ctx.moveTo(boss.x-topHalf,topY); ctx.lineTo(boss.x+topHalf,topY);
    ctx.lineTo(boss.x+botHalf,botY); ctx.lineTo(boss.x-botHalf,botY); ctx.closePath(); ctx.fill();
    // animated rings
    ctx.strokeStyle='rgba(120,180,255,0.6)';
    for(let k=0;k<4;k++){ const yy=topY+((G.time*2+k*40)%(botY-topY)); const hh=lerp(topHalf,botHalf,(yy-topY)/(botY-topY));
      ctx.beginPath(); ctx.moveTo(boss.x-hh,yy); ctx.lineTo(boss.x+hh,yy); ctx.stroke(); }
    ctx.restore();
  }
}
function drawShots(){
  ctx.fillStyle=COL.white;
  for(const s of G.pShots){ ctx.fillRect(s.x-1|0,s.y|0,2,4); }
  ctx.fillStyle=COL.yellow;
